package android.view;import java.util.*;public class ViewGroup extends View {public static class LayoutParams {public LayoutParams(int w,int h){}}public List<View> children=new ArrayList<>();public List<MotionEvent> dispatched=new ArrayList<>();public ViewGroup(int id){super(id);}public ViewGroup(){super();}public void addView(View v){children.add(v);v.parent=this;}public int getChildCount(){return children.size();}public View getChildAt(int i){return children.get(i);}public View findViewById(int n){if(id==n)return this;for(View v:children){View r=v.findViewById(n);if(r!=null)return r;}return null;}public boolean dispatchTouchEvent(MotionEvent e){dispatched.add(e);return true;}}
